const ledgerFor = (t: C.CapitalType): C.CapitalLedger => {
  const es = ledger.filter((e) => e.capitalType === t);
  const s = (k: C.CapitalLedgerEntry["kind"]) => es.filter((e) => e.kind === k).reduce((a, e) => a + e.amount, 0);
  const received = s("RECEIPT") + s("ADJUSTMENT"), deployed = s("DEPLOYMENT"), returned = s("RETURN") + s("REPAYMENT") + s("REVENUE_SHARE");
  const ivts = investments.filter((x) => x.capitalType === t); const name = (i: string) => investors.find((x) => x.id === i)?.name ?? i;
  const detail: C.CapitalLedger["detail"] = t === "OWN" ? { capTable: ivts.map((x) => ({ investor: name(x.investorId), invested: x.received, committed: x.committed, ownershipPct: Number(x.economics.ownershipPct ?? 0), round: String(x.economics.round ?? "—"), status: x.status })), shareholders: ivts.length, investorOwnershipPct: 6.25, foundersOwnershipPct: 93.75, valuation: 4_000_000 }
    : t === "POWER" ? { providers: ivts.map((x) => ({ investor: name(x.investorId), committed: x.committed, deployed: x.deployed, available: x.received - x.deployed, returnPct: 9, status: x.status })), utilizationPct: received ? R((deployed / received) * 1000) / 10 : 0, returns: returned }
    : t === "SCALE" ? { participants: [], repayment: 0, outstandingToCap: 0 } : { partners: [] };
  return { capitalType: t, ccy: "USD", balances: { committed: s("COMMITMENT"), received, deployed, returned, available: Math.max(0, received - deployed + (t === "POWER" ? returned : 0)), outstanding: Math.max(0, deployed - returned) }, detail, entries: [...es].reverse() };
};
